begin;select no_plan();
select is((select count(*)::int from gina.security_schema_findings()),0,'application catalog has no RLS/grant/search-path findings');
create table public.security_negative_fixture(id uuid);
select ok(exists(select 1 from gina.security_schema_findings() where code='rls_off' and object_name='public.security_negative_fixture'),'new unprotected table detected');
alter table public.security_negative_fixture enable row level security;
select ok(not exists(select 1 from gina.security_schema_findings() where code='rls_off' and object_name='public.security_negative_fixture'),'RLS fix removes finding');
grant select on public.security_negative_fixture to anon;
select ok(exists(select 1 from gina.security_schema_findings() where code='anon_table_grant' and object_name='public.security_negative_fixture'),'anon read grant detected');
revoke all on public.security_negative_fixture from anon,authenticated;
grant select on public.security_negative_fixture to authenticated;
select ok(exists(select 1 from gina.security_schema_findings() where code='authenticated_grant_without_policy' and object_name='public.security_negative_fixture:SELECT'),'grant without matching policy detected');
create policy security_fixture on public.security_negative_fixture for select to authenticated using(true);
select ok(not exists(select 1 from gina.security_schema_findings() where code='authenticated_grant_without_policy' and object_name='public.security_negative_fixture:SELECT'),'matching policy removes finding');
create function public.security_negative_function() returns int language sql security definer as $$select 1$$;
select ok(exists(select 1 from gina.security_schema_findings() where code='definer_search_path_missing' and object_name like '%security_negative_function()'),'unsafe definer search path detected');
alter function public.security_negative_function() set search_path='';
select ok(not exists(select 1 from gina.security_schema_findings() where code='definer_search_path_missing' and object_name like '%security_negative_function()'),'fixed search path removes finding');
set local role authenticated;
select throws_ok($$select * from gina.security_schema_findings()$$,'42501',null,'catalog helper not exposed to app clients');
reset role;select * from finish();rollback;
